target.css:
:root {
  --ink: #1d2540;
  --muted: #69718a;
  --paper: #fffdf7;
  --line: #e7e2d8;
  --navy: #27356d;
  --lavender: #ececff;
  --live: #d74c5c;
  --live-soft: #fff0f1;
  --footer: #faf8f2;
  --amber: #f2ab3d;
  --blue: #5585d5;
  --pink: #cf6f9b;
}

* {
  box-sizing: border-box;
}

.broadcast-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 10px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: 19px;
  line-height: 1.1;
}

.live-badge {
  padding: 4px 7px;
  color: var(--live);
  background: var(--live-soft);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.show-strip {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 10px;
  padding: 9px 10px;
  background: var(--lavender);
  border-radius: 11px;
}

.show-icon {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  color: var(--paper);
  background: var(--navy);
  border-radius: 8px;
  font-size: 16px;
  font-weight: 700;
}

.show-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.show-copy p,
.show-copy span {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.15;
}

.show-copy p {
  font-weight: 700;
  letter-spacing: 0.6px;
}

.show-copy strong {
  font-size: 13px;
  line-height: 1.1;
}

.show-strip time {
  color: var(--navy);
  font-size: 14px;
  font-weight: 800;
}

.queue {
  padding: 11px 16px 6px;
}

.queue-heading,
.slot,
.card-footer {
  display: flex;
  align-items: center;
}

.queue-heading {
  justify-content: space-between;
  margin-bottom: 3px;
}

h2 {
  margin-bottom: 0;
  font-size: 12px;
}

.queue-heading span,
.duration,
.card-footer span {
  color: var(--muted);
  font-size: 10px;
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.slot {
  gap: 9px;
  min-height: 32px;
  border-top: 1px solid var(--line);
}

.slot time {
  width: 33px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.slot-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.amber {
  background: var(--amber);
}

.blue {
  background: var(--blue);
}

.pink {
  background: var(--pink);
}

.slot-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  line-height: 1.1;
}

.slot-copy strong {
  font-size: 12px;
}

.slot-copy span {
  color: var(--muted);
  font-size: 10px;
}

.card-footer {
  justify-content: space-between;
  padding: 8px 16px;
  background: var(--footer);
  border-top: 1px solid var(--line);
}

button {
  padding: 5px 9px;
  color: var(--paper);
  background: var(--navy);
  border: 0;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
}

